const crawlPage = (engineToUse, keyword) => {
    //keyword = keyword.replace(/\s/g, '+');
    var url = location.href + "getContents.php" + "?kw=" + keyword + '&engine=' + engineToUse;
    url = encodeURI(url);
    console.log(url);
    $.ajax({
        url:url,
        dataType: 'json',
        success:function(json){
            loadSearchResults(json);
        },
        error:function(){

        }
   });
}
const loadSearchResults = ($results) => {
    $appendTo = $(".web-results .results")
    $appendTo.html("");//Reset the container before loading another result
    for(var result = 0; result < $results.length; result++){
        var theResult = '<span class = "result"><a target = "_blank" href = "' + $results[result].link + '"><strong>' + $results[result].title + '</strong><span class="bread-crumbs">' + $results[result].bread + '</span><p>' + $results[result].desc + '</p></a></span>'
        $appendTo.append(theResult); 
    }
}

var clicked1 = false;
const showPageDesc = (elem) => {
    var result = $(".sch-rls .web-results .results .result:hover > p, .sch-rls .web-results .results .result")
    if(clicked1){
        elem.attr("data-status", "0");
        result.removeClass("show-dsc")
        clicked1 = false;
    }
    else{
        elem.attr("data-status", "1");
        result.addClass("show-dsc")
        clicked1 = true;
    }
}

$(document).ready(function(){
    $defaultSearchEngine = "bing";
    // Replace above on time of search with
    // the one modifed from System Settings
    crawlPage($defaultSearchEngine, "James Bond");
    $(".sch-rls .web-results .rlt-header .showl-btn .status").click(
        function(){
            showPageDesc($(this));
        }
    );
    var $typingTimer;
    var $doneTypingInterval = 800;
    var $input = $('.front-header .search-bar input');
    $input.on('keyup', function () {
        clearTimeout($typingTimer);
        $typingTimer = setTimeout(doneTyping, $doneTypingInterval, $defaultSearchEngine ,$input);
    });
    $input.on('keydown', function () {
        clearTimeout($typingTimer);
    });
    function doneTyping ($defaultSearchEngine, $input) {
        crawlPage($defaultSearchEngine, $($input).val());
    }
});
